samples.listCertificates:
require "teachmehipaa"

client = TeachMeHipaa::Client.new(
  client_id: ENV.fetch("TMH_CLIENT_ID"),
  client_secret: ENV.fetch("TMH_CLIENT_SECRET"),
  environment: :sandbox,
)

certificates = client.certificates.list(
  subject_id: "sub_01JD80AB2C3D4E5F6G7H8J9K0M",
)
certificates.auto_paging_each { |cert| puts cert.expires_at }
